\begin{assumption}[Well-posedness]\label{ass:strong_sol_exist_unique}
For every $\vartheta_0\in\Theta\times\sM$ and every random variable $Z_0$, independent of the driving Brownian motion, with law $\nu_0\in\mathcal P_2(\sX\times\sV)$, the mean-field system \eqref{eq:general_mf_system_opt}--\eqref{eq:general_mf_system_x} admits a pathwise unique strong solution on every finite time interval. Moreover, $\nu_t:=\mathrm{Law}(Z_t)\in\mathcal P_2(\sX\times\sV)$ for all finite $t\ge0$. Furthermore, assume one of
\begin{enumerate}[(i)]
    \item For any $\vartheta\in\Theta\times\sM,z\in\sX\times\sV$, the diffusion coefficient $\sigma_{\Pi_{\theta}(\vartheta)}(z)$ is constant.
    \item For any $\vartheta\in\Theta\times\sM,z\in\sX\times\sV$, the following linear growth condition on the drift and diffusion 
\begin{equation*}
    \| b_{\Pi_\theta(\vartheta)}(z)\|+\|\sigma_{\Pi_\theta(\vartheta)}(z)\|\le K(1+\|\theta\|+\|z\|).
\end{equation*}
\end{enumerate}
\end{assumption}

results.exact_tex:
\begin{theorem}[Finite-particle interaction error]
\label{thm:finite_particle_error}
Suppose \ref{ass:strong_sol_exist_unique}, \ref{ass:twisted_joint_strong_monotonicity}--\ref{ass:mf_bounded_second_moment} hold.
Let $(\vartheta_t^N,Z_t^1,\ldots,Z_t^N)$ solve the particle system
\eqref{eq:general_particle_system_opt}--\eqref{eq:general_particle_system_x}
with the same Brownian motions and the synchronous initial conditions
\(\vartheta_0^N=\bar\vartheta_0\) and \(Z_0^i=\bar Z_0^i\).
Let \((\bar\vartheta_t,\bar Z_t^1,\ldots,\bar Z_t^N)\) solve the \(N\)-copy mean-field system \eqref{eq:n-copy-1}--\eqref{eq:n-copy-2}. Then, for every
$t\ge0$,
\[
    \Ltwonorm[\big]{\mathbf{d}\big((\vartheta^N_t,\nu_t^N),(\bar\vartheta_t,\bar\nu_t^{[N]})\big)}
    \le
    \tfrac{L_\Psi}{\rho}
    \sqrt{\tfrac{\kappa V_F}{N}}
    \left(1-e^{-\rho t}\right),
\]
where $\kappa$ is the condition number of
$\mathrm{diag}(D_\vartheta,D_z)$.
\end{theorem}

\begin{theorem}[Parameter error bound of particle system]\label{thm:parameter_error_full}
    Suppose \ref{ass:strong_sol_exist_unique}--\ref{ass:mf_bounded_second_moment} hold. Assume \(\vartheta_0^N\) is deterministic and \(Z_0^1,\ldots,Z_0^N\) are i.i.d.\ with common law \(\nu_0\), independently of the mutually independent Brownian motions. Then the $\mathrm{L}^2$ parameter error satisfies
\begin{equation*}
\Ltwonorm{\theta^N_t-\theta_\star}\le \sqrt{\kappa}\,e^{-\rho t}
\mathbf d_0+\tfrac{L_\Psi}{\rho}
\sqrt{\tfrac{\kappa V_F}{N}}
\left(1-e^{-\rho t}\right),
\end{equation*}
with
\(\mathbf d_0:=\mathbf d((\vartheta^N_0,\nu_0),(\vartheta_\star,\nu_{\theta_\star}))\), the initial distance from the stationary mean-field solution. Consequently,
\begin{align*}
\lim_{N\to\infty}\limsup_{t\to\infty}
\Ltwonorm{\theta_t^N-\theta_\star}=0.
\end{align*}
\end{theorem}

\begin{corollary}[Separate sufficient conditions for
\ref{ass:twisted_joint_strong_monotonicity}]
\label{cor:separate_monotonicity}
Let
\begin{align*}
\kappa:=
\frac{\lambda_{\max}(\operatorname{diag}(D_\vartheta,D_z))}
{\lambda_{\min}(\operatorname{diag}(D_\vartheta,D_z))}.
\end{align*}
Define
\begin{align*}
H:=
\begin{pmatrix}
\rho_\Psi-\frac12\kappa L_\sigma^2&
-\frac12\sqrt\kappa(L_\Psi L_F+L_b)\\
-\frac12\sqrt\kappa(L_\Psi L_F+L_b)&
\rho_b-\frac12\kappa L_\sigma^2
\end{pmatrix}.
\end{align*}
Under \ref{ass:psi_assumptions},
\ref{ass:lipschitz_F}, and \ref{ass:SDE_assumptions},
\ref{ass:twisted_joint_strong_monotonicity} holds if
\begin{equation}
\label{eq:cor3_indv_cond_joint}
\begin{aligned}
2\rho_\Psi-\kappa L_\sigma^2&>0,\\
2\rho_b-\kappa L_\sigma^2&>0,\\
(2\rho_\Psi-\kappa L_\sigma^2)
(2\rho_b-\kappa L_\sigma^2)
&>
\kappa(L_\Psi L_F+L_b)^2.
\end{aligned}
\end{equation}
More precisely, under \eqref{eq:cor3_indv_cond_joint}, $H$ is positive
definite and \ref{ass:twisted_joint_strong_monotonicity} holds with rate
$\rho=\lambda_{\min}(H)>0$.
A simpler sufficient condition is
\begin{equation}
\label{eq:cor3_indv_cond_separate}
\rho_\Psi
>
\frac{\kappa L_\sigma^2}{2}
+
\frac{\sqrt\kappa}{2}(L_\Psi L_F+L_b),
\qquad
\rho_b
>
\frac{\kappa L_\sigma^2}{2}
+
\frac{\sqrt\kappa}{2}(L_\Psi L_F+L_b).
\end{equation}
Consequently, if \ref{ass:strong_sol_exist_unique} also holds,
Theorem~\ref{thm:twisted_joint_strong_monotonicity} gives exponential
contraction.
\end{corollary}

\begin{corollary}[Projected-field sufficient condition for
\ref{ass:twisted_joint_strong_monotonicity}]
\label{cor:projected_strong_convexity}
Suppose \ref{ass:auxiliary_separation} and
\ref{ass:auxiliary_dissipation} hold, and suppose that
$\sigma_\theta(z)$ is independent of $(\theta,z)$.  If
\begin{align*}
c:=\beta\rho_\Phi-A_\theta-A_x>0,
\end{align*}
define
\begin{align*}
K_\vartheta:=
\begin{pmatrix}
cI_{d_\theta}&0\\
0&D_m
\end{pmatrix},
\qquad
K_z:=
\begin{pmatrix}
cI_{d_x}&0\\
0&D_v
\end{pmatrix},
\end{align*}
and
\begin{align*}
\rho:=
\min\left\{
\lambda_{\min}\!\left(
D_\vartheta^{-1/2}K_\vartheta D_\vartheta^{-1/2}
\right),
\lambda_{\min}\!\left(
D_z^{-1/2}K_zD_z^{-1/2}
\right)
\right\}.
\end{align*}
Then $\rho>0$ and
\ref{ass:twisted_joint_strong_monotonicity} holds with the
matrices $D_\vartheta,D_z$ and rate $\rho$.  Consequently, if
\ref{ass:strong_sol_exist_unique} also holds,
Theorem~\ref{thm:twisted_joint_strong_monotonicity} gives exponential
contraction.
\end{corollary}

\begin{lemma}[Volume preservation of schemes]\label{lemma:vol_preserve_ode} Consider the ODE obtained by taking the \textit{A, B} parts of \eqref{eq:alg_underdamped}. Assuming the associated flow is globally defined and the vector field in $C^1$ is continuously differentiable, then the flow is volume preserving. In particular, let $\varphi_t$ denote the flow generated by the ODE, then
\begin{equation*}
    \mathrm{det}D\varphi_t(z)=1,
\end{equation*}
where $D$ denotes the total derivative and for any $z:=(\theta,m,X,V)$ and $t>0$. 

Moreover, let $\Phi_h$ be the one-step map described by the \textit{B,A} sections of the discretisation \eqref{eq:full_discretisation}. Then $\Phi_h$ is also volume preserving. In particular,
\begin{equation*}
    \mathrm{det} D\Phi_h(z)=1,
\end{equation*}
for any $z:=(\theta,m,X,V)$ and $h$ the step-size.
\end{lemma}
